  2983
  2984      if ((leaderData.GetPartitionId() != mLeaderData.GetPartitionId()) ||
  2985          (leaderData.GetWeighting() != mLeaderData.GetWeighting()) || (leaderData.GetLeaderRouterId() != GetLeaderId()))
  2986      {
  2987          if (mRole == OT_DEVICE_ROLE_CHILD)
  2988          {
  2989              SetLeaderData(leaderData.GetPartitionId(), leaderData.GetWeighting(), leaderData.GetLeaderRouterId());
  2990              mRetrieveNewNetworkData = true;
  2991          }
  2992          else
  2993          {
  2994              ExitNow(error = OT_ERROR_DROP);
  2995          }
  2996      }
  2997      else if (!mRetrieveNewNetworkData)
  2998      {
  2999          int8_t diff;
  3000
  3001          if (IsFullNetworkData())
  3002          {
  3003              diff = static_cast<int8_t>(leaderData.GetDataVersion() - Get<NetworkData::Leader>().GetVersion());
  3004          }
  3005          else
  3006          {
  3007              diff =
  3008                  static_cast<int8_t>(leaderData.GetStableDataVersion() - Get<NetworkData::Leader>().GetStableVersion());
  3009          }
  3010
  3011          VerifyOrExit(diff > 0);
  3012      }
  3013
  3014      // Active Timestamp
  3015      if (Tlv::GetTlv(aMessage, Tlv::kActiveTimestamp, sizeof(activeTimestamp), activeTimestamp) == OT_ERROR_NONE)
  3016      {
  3017          const MeshCoP::Timestamp *timestamp;
  3018
  3019          VerifyOrExit(activeTimestamp.IsValid(), error = OT_ERROR_PARSE);
  3020          timestamp = Get<MeshCoP::ActiveDataset>().GetTimestamp();
  3021
  3022          // if received timestamp does not match the local value and message does not contain the dataset,
  3023          // send MLE Data Request
  3024          if ((timestamp == NULL || timestamp->Compare(activeTimestamp) != 0) &&
  3025              (Tlv::GetOffset(aMessage, Tlv::kActiveDataset, activeDatasetOffset) != OT_ERROR_NONE))
  3026          {
  3027              ExitNow(dataRequest = true);
  3028          }
  3029      }
  3030      else
  3031      {
  3032          activeTimestamp.SetLength(0);
  3033      }
  3034
  3035      // Pending Timestamp
  3036      if (Tlv::GetTlv(aMessage, Tlv::kPendingTimestamp, sizeof(pendingTimestamp), pendingTimestamp) == OT_ERROR_NONE)
  3037      {
  3038          const MeshCoP::Timestamp *timestamp;
  3039
  3040          VerifyOrExit(pendingTimestamp.IsValid(), error = OT_ERROR_PARSE);
  3041          timestamp = Get<MeshCoP::PendingDataset>().GetTimestamp();
  3042
  3043          // if received timestamp does not match the local value and message does not contain the dataset,
  3044          // send MLE Data Request
  3045          if ((timestamp == NULL || timestamp->Compare(pendingTimestamp) != 0) &&
  3046              (Tlv::GetOffset(aMessage, Tlv::kPendingDataset, pendingDatasetOffset) != OT_ERROR_NONE))
  3047          {
  3048              ExitNow(dataRequest = true);
  3049          }
  3050      }
  3051      else
  3052      {
  3053          pendingTimestamp.SetLength(0);
  3054      }
  3055
  3056      if (Tlv::GetOffset(aMessage, Tlv::kNetworkData, networkDataOffset) == OT_ERROR_NONE)
  3057      {
  3058          error =
  3059              Get<NetworkData::Leader>().SetNetworkData(leaderData.GetDataVersion(), leaderData.GetStableDataVersion(),
  3060                                                        !IsFullNetworkData(), aMessage, networkDataOffset);
  3061          SuccessOrExit(error);
  3062      }
  3063      else
  3064      {
  3065          ExitNow(dataRequest = true);
  3066      }
  3067
  3068      // Active Dataset
